urlset:
{%- set site_url = "https://swimfrancisco.com" %}
{%- for entry in entries %}
  {%- set canonical_url = entry.permalink
    | replace(from=site_url ~ "/es/", to=site_url ~ "/")
    | replace(from=site_url ~ "/zh-Hant/", to=site_url ~ "/")
    | replace(from=site_url ~ "/fil/", to=site_url ~ "/")
    | replace(from=site_url ~ "/vi/", to=site_url ~ "/")
    | replace(from=site_url ~ "/fi/", to=site_url ~ "/") %}
  {%- set es_url = canonical_url | replace(from=site_url ~ "/", to=site_url ~ "/es/") %}
  {%- set zh_url = canonical_url | replace(from=site_url ~ "/", to=site_url ~ "/zh-Hant/") %}
  {%- set fil_url = canonical_url | replace(from=site_url ~ "/", to=site_url ~ "/fil/") %}
  {%- set vi_url = canonical_url | replace(from=site_url ~ "/", to=site_url ~ "/vi/") %}
  {%- set fi_url = canonical_url | replace(from=site_url ~ "/", to=site_url ~ "/fi/") %}

    {{ entry.permalink | safe }}







    {%- if entry.updated %}
    {{ entry.updated }}
    {%- endif %}

{%- endfor %}
